ext('c12_hin_ch23',[
C("🎭","व्यंग्य क्या होता है",["बात को सीधे न कहकर चुभने वाले ढंग से कहना","हँसी में कड़वा सच","समाज की कमियों पर चोट","विडंबना का प्रयोग"],"इस कविता को समझने के लिए पहले व्यंग्य को समझिए। व्यंग्य वह शैली है जिसमें बात सीधे न कहकर इस ढंग से कही जाती है कि सुनने वाले को चुभे भी और सोचने पर भी मजबूर करे। कई बार इसमें हँसी का सहारा लिया जाता है, पर उसके भीतर कड़वा सच छिपा होता है। व्यंग्य का उद्देश्य समाज की कमियों, राजनीति के पाखंड और व्यवस्था की ख़ामियों पर चोट करना है। इसमें अक्सर विडंबना होती है, यानी जो दिखता है और जो सच है, उसमें बड़ा अंतर। अधिनायक कविता इसी शैली की उत्कृष्ट रचना है।"),
C("✍️","रघुवीर सहाय का परिचय",["जन्म 1929, लखनऊ","कवि, पत्रकार और संपादक","आत्महत्या के विरुद्ध, सीढ़ियों पर धूप में","साहित्य अकादमी पुरस्कार"],"रघुवीर सहाय का जन्म उन्नीस सौ उनतीस में लखनऊ में हुआ। वे कवि, पत्रकार और संपादक थे। उन्होंने नवभारत टाइम्स और दिनमान जैसे प्रसिद्ध पत्रों में काम किया। पत्रकारिता का अनुभव उनकी कविता में साफ़ दिखता है, क्योंकि वे रोज़मर्रा के आम आदमी और राजनीति की सच्चाई को सीधी भाषा में सामने लाते हैं। उनके प्रमुख संग्रह सीढ़ियों पर धूप में और आत्महत्या के विरुद्ध हैं। उन्हें साहित्य अकादमी पुरस्कार भी मिला। वे नई कविता आंदोलन के प्रमुख कवियों में गिने जाते हैं।"),
C("❓","कविता का मूल प्रश्न",["राष्ट्रगीत में भाग्य विधाता कौन","जयगान किसका हो रहा है","क्या वह जनता के हाल को जानता है","प्रश्न से व्यंग्य शुरू होता है"],"कविता की शुरुआत एक सीधे प्रश्न से होती है, कि राष्ट्रगीत में भारत के भाग्य को बनाने वाला, यानी भारत भाग्य विधाता कौन है। कवि जानना चाहते हैं कि जिसकी जय हर सुबह स्कूलों में गाई जाती है, वह वास्तव में कौन है और क्या वह उन्हीं लोगों की हालत जानता है जो उसकी जय गा रहे हैं। यह प्रश्न व्यंग्य का आरंभ है। यहाँ कवि राष्ट्रगान का अपमान नहीं करते, बल्कि यह दिखाते हैं कि सत्ता और जनता के बीच कितना बड़ा फ़ासला है।"),
C("👦","हरचरना: आम आदमी का प्रतीक",["फटे कपड़े पहना, भूखा बालक","स्कूल में राष्ट्रगान गाता है","अपनी हालत से अनजान या विवश","आम जनता का प्रतिनिधि"],"कविता का पात्र हरचरना एक ग़रीब बालक है, जो फटे कपड़े पहनकर स्कूल जाता है और सुबह की प्रार्थना सभा में राष्ट्रगान गाता है। वह श्रद्धा से गाता है, पर ख़ुद अभाव में है। हरचरना कोई एक बच्चा नहीं, वह भारत के करोड़ों आम लोगों का प्रतीक है, जो ग़रीबी में भी देश के गीत गाते हैं। कवि दिखाते हैं कि जिनकी हालत सबसे ख़राब है, वही जयगान करने वाले हैं। इस विरोधाभास से कविता में गहरा व्यंग्य पैदा होता है और पाठक का मन भीतर तक हिल जाता है।"),
C("👑","अधिनायक: सत्ता का प्रतीक",["वह जिसकी जय गाई जा रही है","जनता की पीड़ा से बेख़बर","आडंबर और शान में डूबा","सत्ता और जनता की दूरी"],"कविता में अधिनायक का अर्थ है वह सत्ताधारी, जिसकी जय गाई जाती है। कवि बताते हैं कि वह अपनी शान और ठाठ में मग्न है और उसे उस बालक या उसके जैसे करोड़ों लोगों की दशा का कोई पता नहीं। अधिनायक किसी एक व्यक्ति का नहीं, बल्कि पूरी सत्ता और उसके तंत्र का प्रतीक है। कविता का व्यंग्य यही है कि जो लोग जनता के भाग्य का फ़ैसला करने बैठे हैं, वे जनता से कटे हुए हैं। लोकतंत्र का सार यह होना चाहिए कि शासन जनता के दुख को समझे।"),
C("⚖️","लोकतंत्र की विडंबना",["संविधान में जनता सर्वोपरि","व्यवहार में दूरी और भेदभाव","आम आदमी की आवाज़ दबना","जागरूकता की ज़रूरत"],"कविता लोकतंत्र की एक बड़ी विडंबना की ओर इशारा करती है। हमारे संविधान में जनता सर्वोच्च है और सब बराबर हैं। पर व्यवहार में कई बार आम आदमी की बात सुनी नहीं जाती और सत्ता और जनता के बीच दूरी बन जाती है। यही अंतर कवि को पीड़ा देता है। कविता यह भी बताती है कि सुधार तभी होगा जब जनता जागरूक होगी और सवाल पूछेगी। एक लोकतंत्र में सवाल पूछना देशद्रोह नहीं, बल्कि नागरिक का कर्तव्य है, और अधिनायक कविता यही कर्तव्य निभाती है।"),
C("🎨","काव्य शिल्प और भाषा",["सरल बोलचाल की भाषा","प्रश्न शैली","प्रतीकात्मकता: हरचरना और अधिनायक","छंद-मुक्त कविता"],"इस कविता का शिल्प सादा है। भाषा बोलचाल की है, जिसमें अलंकारों की सजावट नहीं, बल्कि सीधी बात है। कविता छंद-मुक्त है, यानी उसमें तुक या मात्राओं का बंधन नहीं। प्रश्न की शैली से शुरुआत होती है और हरचरना तथा अधिनायक प्रतीक के रूप में आते हैं। यह सादगी ही कविता की ताक़त है, क्योंकि सरल भाषा में कही गई कड़वी बात ज़्यादा गहरी चोट करती है। परीक्षा में शिल्प पूछा जाए, तो सरल भाषा, प्रतीक, प्रश्न शैली और व्यंग्य ज़रूर लिखिए।"),
C("📰","पत्रकारिता का प्रभाव",["रघुवीर सहाय पत्रकार भी थे","रोज़मर्रा की ख़बरों जैसी भाषा","आम आदमी के प्रति संवेदना","सीधा और स्पष्ट कथन"],"रघुवीर सहाय की कविता पर उनकी पत्रकारिता का साफ़ असर दिखता है। पत्रकार जैसे आँखों-देखी सच्चाई को सीधे शब्दों में कहता है, वैसे ही वे कविता में ज़मीन की बात करते हैं। उनके विषय आम आदमी, ग़रीबी, राजनीति की चालें और समाज का दोगलापन होते हैं। उनकी भाषा में कृत्रिमता नहीं है, इसलिए वह सीधे पाठक तक पहुँचती है। इसीलिए उन्हें नई कविता का ऐसा कवि माना जाता है जिसने कविता को ख़बर के क़रीब पर संवेदना के साथ पहुँचाया।"),
C("🏫","स्कूल का राष्ट्रगान",["हर सुबह प्रार्थना सभा","श्रद्धा से गाना","अर्थ समझकर गाने की ज़रूरत","राष्ट्र के प्रति ज़िम्मेदारी"],"कविता की पृष्ठभूमि स्कूल की सुबह की प्रार्थना सभा है, जहाँ राष्ट्रगान गाया जाता है। यह हम सबके अनुभव से जुड़ा है। हम राष्ट्रगान सम्मान से गाते हैं, पर क्या उसका अर्थ भी सोचते हैं? कवि हमें यही सोचने पर मजबूर करते हैं। राष्ट्रगान गाना केवल रस्म नहीं, बल्कि देश के हर नागरिक की भलाई के लिए काम करने का संकल्प है। हम जब सुबह गाएँ, तो सोचें कि हमारे आसपास कोई भूखा या बेबस न रहे, और इसके लिए हम अपनी तरफ़ से क्या कर सकते हैं।"),
C("🤲","हमारी ज़िम्मेदारी",["गरीबों के प्रति संवेदना","अपने अधिकार और कर्तव्य जानना","मतदान और जागरूकता","छोटी मदद भी महत्वपूर्ण"],"कविता केवल सत्ता पर सवाल नहीं उठाती, वह हमें भी सोचने को कहती है। एक नागरिक के रूप में हमारी भी ज़िम्मेदारी है। हमें अपने अधिकारों के साथ कर्तव्य भी जानने चाहिए। मतदान जैसे अवसर पर सही जानकारी के साथ वोट देना चाहिए। अपने आसपास के ज़रूरतमंदों की छोटी-छोटी मदद भी करनी चाहिए, जैसे किसी बच्चे की किताब या कॉपी में सहायता। जब समाज का हर व्यक्ति संवेदनशील होता है, तभी हरचरना जैसे बच्चों की हालत बदल सकती है और जयगान का अर्थ सच्चा हो सकता है।"),
C("📌","कविता का सार",["राष्ट्रगीत और भाग्य विधाता का प्रश्न","हरचरना: ग़रीब आम आदमी","अधिनायक: जनता से कटी सत्ता","संदेश: जागरूकता और संवेदना"],"अब कविता का सार दोहरा लें। रघुवीर सहाय की अधिनायक कविता में कवि पूछते हैं कि राष्ट्रगीत में भारत का भाग्य विधाता कौन है। हरचरना नामक ग़रीब बालक फटे कपड़ों में जिसकी जय गाता है, वह अधिनायक उसकी हालत से बेख़बर है। कविता सत्ता और जनता की दूरी और लोकतंत्र की विडंबना पर तीखा व्यंग्य करती है। संदेश है कि जनता को जागरूक होना चाहिए और सत्ता को संवेदनशील। इसे पाँच वाक्यों में अपने शब्दों में लिखकर देखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि का परिचय","हरचरना और अधिनायक किसके प्रतीक","कविता में व्यंग्य कहाँ है","मूल भाव लिखिए"],"परीक्षा के प्रश्न देखिए। पहला, कवि का परिचय दीजिए। उत्तर, रघुवीर सहाय, जन्म उन्नीस सौ उनतीस लखनऊ, पत्रकार और कवि, संग्रह आत्महत्या के विरुद्ध। दूसरा, हरचरना और अधिनायक किसके प्रतीक हैं? उत्तर, आम आदमी और सत्ता के। तीसरा, व्यंग्य कहाँ है? उत्तर, जो ग़रीब है वही जयगान गाता है और जिसका गान है, वह बेख़बर है। चौथा, मूल भाव? उत्तर, लोकतंत्र की विडंबना और सत्ता तथा जनता की दूरी। उत्तर पूरे वाक्य में लिखिए।"),
Q("कविता में हरचरना के माध्यम से कवि क्या कहना चाहते हैं?","देश के करोड़ों ग़रीब लोग भूखे और बेबस होकर भी जयगान करते हैं, जबकि सत्ता उनकी हालत से बेख़बर है।","एक सोचने वाला प्रश्न। कविता में हरचरना के माध्यम से कवि क्या कहना चाहते हैं? सोचिए। ... देश के करोड़ों ग़रीब लोग भूखे और बेबस होकर भी जयगान करते हैं, जबकि सत्ता उनकी हालत से बेख़बर है। यही कविता का व्यंग्य और संदेश है।"),
],7)
